def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Colors on the perimeter are boundary bars; non-background colors
    # away from the perimeter are markers.
    markers = [(r, c) for r in range(1, h - 1) for c in range(1, w - 1)
               if grid[r][c] != bg]
    if not markers:
        return out
    marker_color = grid[markers[0][0]][markers[0][1]]
    marker_set = set(markers)
    bar_color = next((v for v in counts if v != bg and v != marker_color), None)

    for r, c in markers:
        out[r][c] = 4

    # Perimeter bar segments project inward, with their first cell serving
    # as the unprojected anchor.
    edges = [
        ([(0, c) for c in range(w)], (1, 0)),
        ([(h - 1, c) for c in range(w)], (-1, 0)),
        ([(r, 0) for r in range(h)], (0, 1)),
        ([(r, w - 1) for r in range(h)], (0, -1)),
    ]
    for cells, (dr, dc) in edges:
        i = 0
        while i < len(cells):
            r, c = cells[i]
            if grid[r][c] != bar_color:
                i += 1
                continue
            j = i
            while j < len(cells) and grid[cells[j][0]][cells[j][1]] == bar_color:
                j += 1
            for k in range(i + 1, j):
                r, c = cells[k]
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if (rr, cc) in marker_set:
                        break
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = marker_color
                    rr += dr
                    cc += dc
            i = j

    # Markers project in straight lines toward aligned perimeter bars.
    for r, c in markers:
        options = []
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            rr, cc = r + dr, c + dc
            distance = 1
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == bar_color:
                    options.append((distance, dr, dc))
                    break
                if grid[rr][cc] != bg:
                    break
                rr += dr
                cc += dc
                distance += 1
        if options:
            _, dr, dc = min(options)
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bar_color:
                if (rr, cc) not in marker_set:
                    out[rr][cc] = marker_color
                rr += dr
                cc += dc

